    const paymentComparison="<div style='margin:22px 0;border:1px solid #e8ebf0;border-radius:8px;overflow:hidden'><div style='background:#f7f8fa;padding:12px 14px;font-size:13px;font-weight:700;color:#0f2141'>CHOOSE YOUR PAYMENT METHOD</div><div style='display:flex;justify-content:space-between;gap:14px;padding:13px 14px;border-top:1px solid #e8ebf0;font-size:13px'><span><strong>E-transfer</strong><br/><span style='font-size:11px;color:#687386'>No additional payment fee</span></span><strong style='white-space:nowrap'>"+money(amountDue)+"</strong></div>"+(paymentLinkData.card?"<div style='display:flex;justify-content:space-between;gap:14px;padding:13px 14px;border-top:1px solid #e8ebf0;font-size:13px'><span><strong>Credit card (Square)</strong><br/><span style='font-size:11px;color:#687386'>"+(cardFee>0?"Includes the optional card fee and HST":"No additional payment fee")+"</span></span><strong style='white-space:nowrap'>"+money(amountDue+cardFee+cardFeeTax)+"</strong></div>":"")+"</div>";
